&lt;span class=&#34;token function&#34;&gt;Sort-Object&lt;/span&gt; HandleDelta &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Descending &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;First 30 &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;判断：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;HandleDelta&lt;/code&gt; 很高、&lt;code&gt;InstanceDelta=0&lt;/code&gt;：更像现有进程内部泄漏；&lt;/li&gt;
&lt;li&gt;&lt;code&gt;HandleDelta&lt;/code&gt; 和 &lt;code&gt;InstanceDelta&lt;/code&gt; 都很高：更像不断产生新进程。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;十一、查看进程路径、命令行和父进程&#34;&gt;&lt;a href=&#34;#十一、查看进程路径、命令行和父进程&#34; class=&#34;headerlink&#34; title=&#34;十一、查看进程路径、命令行和父进程&#34;&gt;&lt;/a&gt;十一、查看进程路径、命令行和父进程&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt; = 12345

&lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_Process `
    &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token keyword&#34;&gt;Filter&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;ProcessId=&lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt;&#34;&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
    ProcessId&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    ParentProcessId&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Name&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    ExecutablePath&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    CreationDate&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    CommandLine &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-List&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;父进程详情：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt; = 12345

&lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_Process `
    &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token keyword&#34;&gt;Filter&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;ProcessId=&lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt;&#34;&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$parent&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_Process `
        &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token keyword&#34;&gt;Filter&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;ProcessId=&lt;span class=&#34;token function&#34;&gt;$&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ParentProcessId&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&#34;&lt;/span&gt;

    &lt;span class=&#34;token namespace&#34;&gt;[PSCustomObject]&lt;/span&gt;@&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
        ChildPID      = &lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ProcessId
        ChildName     = &lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Name
        ParentPID     = &lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ParentProcessId
        ParentName    = &lt;span class=&#34;token variable&#34;&gt;$parent&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Name
        ParentPath    = &lt;span class=&#34;token variable&#34;&gt;$parent&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ExecutablePath
        ParentCommand = &lt;span class=&#34;token variable&#34;&gt;$parent&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;CommandLine
    &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Format-List&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;十二、查看完整进程祖先链&#34;&gt;&lt;a href=&#34;#十二、查看完整进程祖先链&#34; class=&#34;headerlink&#34; title=&#34;十二、查看完整进程祖先链&#34;&gt;&lt;/a&gt;十二、查看完整进程祖先链&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Get-ProcessParentChain&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;param&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
        &lt;span class=&#34;token namespace&#34;&gt;[Parameter(Mandatory)]&lt;/span&gt;
        &lt;span class=&#34;token namespace&#34;&gt;[int]&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$ProcessId&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

    &lt;span class=&#34;token variable&#34;&gt;$allProcesses&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_Process
    &lt;span class=&#34;token variable&#34;&gt;$processMap&lt;/span&gt; = @&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

    &lt;span class=&#34;token keyword&#34;&gt;foreach&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt; in &lt;span class=&#34;token variable&#34;&gt;$allProcesses&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
        &lt;span class=&#34;token variable&#34;&gt;$processMap&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token namespace&#34;&gt;[int]&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ProcessId&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; = &lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

    &lt;span class=&#34;token variable&#34;&gt;$currentId&lt;/span&gt; = &lt;span class=&#34;token variable&#34;&gt;$ProcessId&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$level&lt;/span&gt; = 0

    &lt;span class=&#34;token keyword&#34;&gt;while&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$processMap&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ContainsKey&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$currentId&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
        &lt;span class=&#34;token variable&#34;&gt;$current&lt;/span&gt; = &lt;span class=&#34;token variable&#34;&gt;$processMap&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$currentId&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;

        &lt;span class=&#34;token namespace&#34;&gt;[PSCustomObject]&lt;/span&gt;@&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
            Level          = &lt;span class=&#34;token variable&#34;&gt;$level&lt;/span&gt;
            PID            = &lt;span class=&#34;token variable&#34;&gt;$current&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ProcessId
            ParentPID      = &lt;span class=&#34;token variable&#34;&gt;$current&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ParentProcessId
            Name           = &lt;span class=&#34;token variable&#34;&gt;$current&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Name
            ExecutablePath = &lt;span class=&#34;token variable&#34;&gt;$current&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ExecutablePath
            CommandLine    = &lt;span class=&#34;token variable&#34;&gt;$current&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;CommandLine
        &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

        &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$current&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ParentProcessId &lt;span class=&#34;token operator&#34;&gt;-eq&lt;/span&gt; 0&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;break&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$current&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ParentProcessId &lt;span class=&#34;token operator&#34;&gt;-eq&lt;/span&gt; &lt;span class=&#34;token variable&#34;&gt;$current&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ProcessId&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;break&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

        &lt;span class=&#34;token variable&#34;&gt;$currentId&lt;/span&gt; = &lt;span class=&#34;token namespace&#34;&gt;[int]&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$current&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ParentProcessId
        &lt;span class=&#34;token variable&#34;&gt;$level&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;++&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

&lt;span class=&#34;token function&#34;&gt;Get-ProcessParentChain&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ProcessId 12345 &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Wrap &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;十三、查看子进程&#34;&gt;&lt;a href=&#34;#十三、查看子进程&#34; class=&#34;headerlink&#34; title=&#34;十三、查看子进程&#34;&gt;&lt;/a&gt;十三、查看子进程&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt; = 12345

&lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_Process &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Where-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ParentProcessId &lt;span class=&#34;token operator&#34;&gt;-eq&lt;/span&gt; &lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
    ProcessId&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    ParentProcessId&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Name&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    CreationDate&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    ExecutablePath&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    CommandLine &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Wrap &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;十四、分析-svchost-exe&#34;&gt;&lt;a href=&#34;#十四、分析-svchost-exe&#34; class=&#34;headerlink&#34; title=&#34;十四、分析 svchost.exe&#34;&gt;&lt;/a&gt;十四、分析 svchost.exe&lt;/h2&gt;&lt;p&gt;&lt;code&gt;svchost.exe&lt;/code&gt; 是 Windows 服务宿主，不要看到句柄高就直接结束。&lt;/p&gt;
&lt;p&gt;查询指定 PID 承载的服务：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt; = 12345

&lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_Service &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Where-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ProcessId &lt;span class=&#34;token operator&#34;&gt;-eq&lt;/span&gt; &lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
    Name&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    DisplayName&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    State&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    StartMode&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    ProcessId&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    PathName &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Wrap &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;查看所有运行中的服务和 PID：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_Service &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Where-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;State &lt;span class=&#34;token operator&#34;&gt;-eq&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Running&#34;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Sort-Object&lt;/span&gt; ProcessId&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; Name &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
    ProcessId&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Name&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    DisplayName&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    StartMode &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;需要重启具体服务时：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Restart-Service&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Name &lt;span class=&#34;token string&#34;&gt;&#34;服务名&#34;&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Force&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;不要随意停止关键系统服务。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;十五、分析-System-进程&#34;&gt;&lt;a href=&#34;#十五、分析-System-进程&#34; class=&#34;headerlink&#34; title=&#34;十五、分析 System 进程&#34;&gt;&lt;/a&gt;十五、分析 System 进程&lt;/h2&gt;&lt;p&gt;&lt;code&gt;System&lt;/code&gt; 通常为 PID 4，代表大量内核和驱动活动。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Get-Process&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Id 4 &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
    Id&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    ProcessName&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    HandleCount&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Threads&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    NonpagedSystemMemorySize64&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    PagedSystemMemorySize64 &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-List&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;如果 &lt;code&gt;System&lt;/code&gt; 句柄持续增长，常见嫌疑包括：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;存储或 USB 驱动；&lt;/li&gt;
&lt;li&gt;网卡、蓝牙、显卡驱动；&lt;/li&gt;
&lt;li&gt;文件系统过滤驱动；&lt;/li&gt;
&lt;li&gt;杀毒软件；&lt;/li&gt;
&lt;li&gt;VPN、虚拟网卡；&lt;/li&gt;
&lt;li&gt;虚拟机；&lt;/li&gt;
&lt;li&gt;磁盘或文件系统异常。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;查看运行中的驱动：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_SystemDriver &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Where-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;State &lt;span class=&#34;token operator&#34;&gt;-eq&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Running&#34;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
    Name&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    DisplayName&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    StartMode&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    State&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    PathName &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Sort-Object&lt;/span&gt; DisplayName &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Wrap &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;纯 PowerShell 可以判断 PID 4 是否持续增长，但不能可靠显示每个内核句柄究竟属于哪个驱动对象。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;十六、检查系统事件日志&#34;&gt;&lt;a href=&#34;#十六、检查系统事件日志&#34; class=&#34;headerlink&#34; title=&#34;十六、检查系统事件日志&#34;&gt;&lt;/a&gt;十六、检查系统事件日志&lt;/h2&gt;&lt;p&gt;查看最近两小时系统警告和错误：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$startTime&lt;/span&gt; = &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;Get-Date&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;AddHours&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;2&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token function&#34;&gt;Get-WinEvent&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;FilterHashtable @&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    LogName   = &lt;span class=&#34;token string&#34;&gt;&#34;System&#34;&lt;/span&gt;
    StartTime = &lt;span class=&#34;token variable&#34;&gt;$startTime&lt;/span&gt;
    Level     = 2&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; 3
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ErrorAction SilentlyContinue &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
    TimeCreated&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    ProviderName&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Id&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    LevelDisplayName&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Message &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Wrap&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;筛选常见磁盘、USB 和驱动问题：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Get-WinEvent&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;FilterHashtable @&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    LogName   = &lt;span class=&#34;token string&#34;&gt;&#34;System&#34;&lt;/span&gt;
    StartTime = &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;Get-Date&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;AddHours&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;6&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ErrorAction SilentlyContinue &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Where-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ProviderName &lt;span class=&#34;token operator&#34;&gt;-match&lt;/span&gt; `
        &lt;span class=&#34;token string&#34;&gt;&#34;Disk|Ntfs|stor|USB|Kernel-PnP|DriverFrameworks|WHEA|volmgr&#34;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
    TimeCreated&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    ProviderName&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Id&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    LevelDisplayName&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Message &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Wrap&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;十七、检查进程数字签名&#34;&gt;&lt;a href=&#34;#十七、检查进程数字签名&#34; class=&#34;headerlink&#34; title=&#34;十七、检查进程数字签名&#34;&gt;&lt;/a&gt;十七、检查进程数字签名&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt; = 12345

&lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_Process `
    &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token keyword&#34;&gt;Filter&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;ProcessId=&lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt;&#34;&lt;/span&gt;

&lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
    ProcessId&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Name&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    ExecutablePath&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    CommandLine &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-List&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ExecutablePath&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Get-AuthenticodeSignature&lt;/span&gt; `
        &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;FilePath &lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ExecutablePath &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
        Status&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
        StatusMessage&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
        SignerCertificate&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
        Path &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Format-List&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;未签名不等于恶意，有签名也不等于没有问题。更应关注异常路径、临时目录运行和名称伪装。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;十八、检查-GDI-和-USER-对象泄漏&#34;&gt;&lt;a href=&#34;#十八、检查-GDI-和-USER-对象泄漏&#34; class=&#34;headerlink&#34; title=&#34;十八、检查 GDI 和 USER 对象泄漏&#34;&gt;&lt;/a&gt;十八、检查 GDI 和 USER 对象泄漏&lt;/h2&gt;&lt;p&gt;某些 GUI 程序会泄漏窗口、菜单、画刷、字体、设备上下文等资源。&lt;/p&gt;
&lt;p&gt;先加载 API：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Add-Type&lt;/span&gt; @&lt;span class=&#34;token string&#34;&gt;&#34;
using System;
using System.Runtime.InteropServices;

public static class GuiResources
{
    [DllImport(&#34;&lt;/span&gt;user32&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;dll&lt;span class=&#34;token string&#34;&gt;&#34;)]
    public static extern int GetGuiResources(
        IntPtr hProcess,
        int uiFlags
    );
}
&#34;&lt;/span&gt;@&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;查看排行榜：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Get-Process&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ErrorAction SilentlyContinue &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;ForEach-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;try&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
        &lt;span class=&#34;token namespace&#34;&gt;[PSCustomObject]&lt;/span&gt;@&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
            PID         = &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Id
            &lt;span class=&#34;token keyword&#34;&gt;Process&lt;/span&gt;     = &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ProcessName
            Handles     = &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;HandleCount
            GDIObjects  = &lt;span class=&#34;token namespace&#34;&gt;[GuiResources]&lt;/span&gt;::GetGuiResources&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Handle&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; 0&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
            USERObjects = &lt;span class=&#34;token namespace&#34;&gt;[GuiResources]&lt;/span&gt;::GetGuiResources&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Handle&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; 1&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
        &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;catch&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Sort-Object&lt;/span&gt; GDIObjects &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Descending &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;First 30 &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;GDI 或 USER 对象持续上涨时，可能出现窗口无法打开、菜单变黑、界面无法刷新、按钮和图标消失等现象。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;十九、长期记录系统句柄&#34;&gt;&lt;a href=&#34;#十九、长期记录系统句柄&#34; class=&#34;headerlink&#34; title=&#34;十九、长期记录系统句柄&#34;&gt;&lt;/a&gt;十九、长期记录系统句柄&lt;/h2&gt;&lt;p&gt;先创建目录：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$AuditRoot&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Join-Path&lt;/span&gt; &lt;span class=&#34;token variable&#34;&gt;$env&lt;/span&gt;:USERPROFILE &lt;span class=&#34;token string&#34;&gt;&#34;Desktop\HandleAudit&#34;&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;New-Item&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ItemType Directory &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Path &lt;span class=&#34;token variable&#34;&gt;$AuditRoot&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Force &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Out-Null&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;每 30 秒记录一次：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$LogPath&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Join-Path&lt;/span&gt; `
    &lt;span class=&#34;token variable&#34;&gt;$env&lt;/span&gt;:USERPROFILE `
    &lt;span class=&#34;token string&#34;&gt;&#34;Desktop\HandleAudit\system_handle_log.csv&#34;&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;while&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token boolean&#34;&gt;$true&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$processes&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Get-Process&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ErrorAction SilentlyContinue

    &lt;span class=&#34;token variable&#34;&gt;$row&lt;/span&gt; = &lt;span class=&#34;token namespace&#34;&gt;[PSCustomObject]&lt;/span&gt;@&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
        Time      = &lt;span class=&#34;token function&#34;&gt;Get-Date&lt;/span&gt;
        Processes = &lt;span class=&#34;token variable&#34;&gt;$processes&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Count
        Handles   = &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$processes&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Measure-Object&lt;/span&gt; HandleCount &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Sum&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Sum
        Threads   = &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
            &lt;span class=&#34;token variable&#34;&gt;$processes&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
            &lt;span class=&#34;token function&#34;&gt;ForEach-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
                &lt;span class=&#34;token keyword&#34;&gt;try&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt; &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Threads&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Count &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;catch&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt; 0 &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;
            &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
            &lt;span class=&#34;token function&#34;&gt;Measure-Object&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Sum
        &lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Sum
        MemoryGB  = &lt;span class=&#34;token namespace&#34;&gt;[math]&lt;/span&gt;::Round&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
            &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$processes&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Measure-Object&lt;/span&gt; WorkingSet64 &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Sum&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Sum &lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt; 1GB&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
            2
        &lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

    &lt;span class=&#34;token variable&#34;&gt;$row&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Export-Csv&lt;/span&gt; `
        &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Path &lt;span class=&#34;token variable&#34;&gt;$LogPath&lt;/span&gt; `
        &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;NoTypeInformation `
        &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Encoding UTF8 `
        &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Append

    &lt;span class=&#34;token variable&#34;&gt;$row&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize
    &lt;span class=&#34;token function&#34;&gt;Start-Sleep&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Seconds 30
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;查看最近记录：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Import-Csv&lt;/span&gt; &lt;span class=&#34;token variable&#34;&gt;$LogPath&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Last 20 &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;二十、长期记录句柄最高的进程&#34;&gt;&lt;a href=&#34;#二十、长期记录句柄最高的进程&#34; class=&#34;headerlink&#34; title=&#34;二十、长期记录句柄最高的进程&#34;&gt;&lt;/a&gt;二十、长期记录句柄最高的进程&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$LogPath&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Join-Path&lt;/span&gt; `
    &lt;span class=&#34;token variable&#34;&gt;$env&lt;/span&gt;:USERPROFILE `
    &lt;span class=&#34;token string&#34;&gt;&#34;Desktop\HandleAudit\top_process_handles.csv&#34;&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;while&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token boolean&#34;&gt;$true&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$time&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Get-Date&lt;/span&gt;

    &lt;span class=&#34;token function&#34;&gt;Get-Process&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ErrorAction SilentlyContinue &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Sort-Object&lt;/span&gt; HandleCount &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Descending &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;First 30 &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;ForEach-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
        &lt;span class=&#34;token namespace&#34;&gt;[PSCustomObject]&lt;/span&gt;@&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
            Time     = &lt;span class=&#34;token variable&#34;&gt;$time&lt;/span&gt;
            PID      = &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Id
            &lt;span class=&#34;token keyword&#34;&gt;Process&lt;/span&gt;  = &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ProcessName
            Handles  = &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;HandleCount
            Threads  = &lt;span class=&#34;token keyword&#34;&gt;try&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt; &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Threads&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Count &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;catch&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt; 0 &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;
            MemoryMB = &lt;span class=&#34;token namespace&#34;&gt;[math]&lt;/span&gt;::Round&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;WorkingSet64 &lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt; 1MB&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; 1&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
        &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Export-Csv&lt;/span&gt; `
        &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Path &lt;span class=&#34;token variable&#34;&gt;$LogPath&lt;/span&gt; `
        &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;NoTypeInformation `
        &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Encoding UTF8 `
        &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Append

    &lt;span class=&#34;token function&#34;&gt;Write-Host&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;已记录：&lt;span class=&#34;token variable&#34;&gt;$time&lt;/span&gt;&#34;&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Start-Sleep&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Seconds 30
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;二十一、检查开机启动项、服务和计划任务&#34;&gt;&lt;a href=&#34;#二十一、检查开机启动项、服务和计划任务&#34; class=&#34;headerlink&#34; title=&#34;二十一、检查开机启动项、服务和计划任务&#34;&gt;&lt;/a&gt;二十一、检查开机启动项、服务和计划任务&lt;/h2&gt;&lt;p&gt;开机启动项：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_StartupCommand &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; `
    Name&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Command&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    Location&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    User &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Sort-Object&lt;/span&gt; Name &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Wrap&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;运行中的服务：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Get-Service&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Where-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Status &lt;span class=&#34;token operator&#34;&gt;-eq&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Running&#34;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Sort-Object&lt;/span&gt; DisplayName &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; Status&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; Name&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; DisplayName &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;运行中的计划任务：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Get-ScheduledTask&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Where-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;State &lt;span class=&#34;token operator&#34;&gt;-eq&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Running&#34;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Select-Object&lt;/span&gt; TaskPath&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; TaskName&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; State &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
&lt;span class=&#34;token function&#34;&gt;Format-Table&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;AutoSize&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;二十二、安全验证可疑程序&#34;&gt;&lt;a href=&#34;#二十二、安全验证可疑程序&#34; class=&#34;headerlink&#34; title=&#34;二十二、安全验证可疑程序&#34;&gt;&lt;/a&gt;二十二、安全验证可疑程序&lt;/h2&gt;&lt;p&gt;记录关闭前总句柄：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$before&lt;/span&gt; = &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Get-Process&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ErrorAction SilentlyContinue &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Measure-Object&lt;/span&gt; HandleCount &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Sum
&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Sum&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;优先尝试正常关闭：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt; = 12345

&lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Get-Process&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Id &lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt; `
    &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ErrorAction SilentlyContinue

&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$null&lt;/span&gt; = &lt;span class=&#34;token variable&#34;&gt;$process&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;CloseMainWindow&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;必要时按 PID 强制结束：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Stop-Process&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Id &lt;span class=&#34;token variable&#34;&gt;$TargetProcessId&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Force&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;重新统计：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token variable&#34;&gt;$after&lt;/span&gt; = &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Get-Process&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ErrorAction SilentlyContinue &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;Measure-Object&lt;/span&gt; HandleCount &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Sum
&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Sum

&lt;span class=&#34;token namespace&#34;&gt;[PSCustomObject]&lt;/span&gt;@&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    Before  = &lt;span class=&#34;token variable&#34;&gt;$before&lt;/span&gt;
    After   = &lt;span class=&#34;token variable&#34;&gt;$after&lt;/span&gt;
    Reduced = &lt;span class=&#34;token variable&#34;&gt;$before&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;token variable&#34;&gt;$after&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Format-List&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;关闭程序后句柄下降很多，说明它贡献较大，但不一定代表它存在泄漏，也可能只是正常占用较高。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;二十三、不能随意结束的系统进程&#34;&gt;&lt;a href=&#34;#二十三、不能随意结束的系统进程&#34; class=&#34;headerlink&#34; title=&#34;二十三、不能随意结束的系统进程&#34;&gt;&lt;/a&gt;二十三、不能随意结束的系统进程&lt;/h2&gt;&lt;p&gt;一般不要直接结束：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-text&#34; data-language=&#34;text&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;System
Registry
smss.exe
csrss.exe
wininit.exe
winlogon.exe
services.exe
lsass.exe
dwm.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;对 &lt;code&gt;svchost.exe&lt;/code&gt;，应先查 PID 对应服务，不要批量结束。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;explorer.exe&lt;/code&gt; 可以重启：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token function&#34;&gt;Stop-Process&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Name explorer &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Force
&lt;span class=&#34;token function&#34;&gt;Start-Process&lt;/span&gt; explorer&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;重启 Explorer 只能验证资源管理器或 Shell 扩展问题，不能修复内核驱动泄漏。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;二十四、常见异常模式&#34;&gt;&lt;a href=&#34;#二十四、常见异常模式&#34; class=&#34;headerlink&#34; title=&#34;二十四、常见异常模式&#34;&gt;&lt;/a&gt;二十四、常见异常模式&lt;/h2&gt;&lt;h3 id=&#34;模式一：单个-PID-句柄持续上涨&#34;&gt;&lt;a href=&#34;#模式一：单个-PID-句柄持续上涨&#34; class=&#34;headerlink&#34; title=&#34;模式一：单个 PID 句柄持续上涨&#34;&gt;&lt;/a&gt;模式一：单个 PID 句柄持续上涨&lt;/h3&gt;&lt;p&gt;可能原因：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;文件句柄未关闭；&lt;/li&gt;
&lt;li&gt;注册表句柄未关闭；&lt;/li&gt;
&lt;li&gt;同步对象泄漏；&lt;/li&gt;
&lt;li&gt;插件或扩展泄漏；&lt;/li&gt;
&lt;li&gt;程序自身缺陷。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;模式二：同名进程越来越多&#34;&gt;&lt;a href=&#34;#模式二：同名进程越来越多&#34; class=&#34;headerlink&#34; title=&#34;模式二：同名进程越来越多&#34;&gt;&lt;/a&gt;模式二：同名进程越来越多&lt;/h3&gt;&lt;p&gt;可能原因：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;父程序不断拉起子进程；&lt;/li&gt;
&lt;li&gt;子进程超时后未退出；&lt;/li&gt;
&lt;li&gt;更新器反复启动；&lt;/li&gt;
&lt;li&gt;IDE、终端或脚本反复创建工具进程；&lt;/li&gt;
&lt;li&gt;浏览器或 WebView2 宿主异常。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;模式三：System-句柄上涨&#34;&gt;&lt;a href=&#34;#模式三：System-句柄上涨&#34; class=&#34;headerlink&#34; title=&#34;模式三：System 句柄上涨&#34;&gt;&lt;/a&gt;模式三：System 句柄上涨&lt;/h3&gt;&lt;p&gt;重点怀疑：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;USB、磁盘或存储驱动；&lt;/li&gt;
&lt;li&gt;VPN、虚拟网卡；&lt;/li&gt;
&lt;li&gt;杀毒软件；&lt;/li&gt;
&lt;li&gt;虚拟机；&lt;/li&gt;
&lt;li&gt;文件系统过滤驱动。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;模式四：svchost-某个-PID-上涨&#34;&gt;&lt;a href=&#34;#模式四：svchost-某个-PID-上涨&#34; class=&#34;headerlink&#34; title=&#34;模式四：svchost 某个 PID 上涨&#34;&gt;&lt;/a&gt;模式四：svchost 某个 PID 上涨&lt;/h3&gt;&lt;p&gt;先查询该 PID 承载的具体服务，再针对服务排查。&lt;/p&gt;
&lt;h3 id=&#34;模式五：Explorer-句柄上涨&#34;&gt;&lt;a href=&#34;#模式五：Explorer-句柄上涨&#34; class=&#34;headerlink&#34; title=&#34;模式五：Explorer 句柄上涨&#34;&gt;&lt;/a&gt;模式五：Explorer 句柄上涨&lt;/h3&gt;&lt;p&gt;重点怀疑：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;右键菜单扩展；&lt;/li&gt;
&lt;li&gt;网盘 Shell 扩展；&lt;/li&gt;
&lt;li&gt;搜索工具；&lt;/li&gt;
&lt;li&gt;压缩软件；&lt;/li&gt;
&lt;li&gt;缩略图生成；&lt;/li&gt;
&lt;li&gt;无响应的外接磁盘或网络路径。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;模式六：浏览器或-WebView2-总量高&#34;&gt;&lt;a href=&#34;#模式六：浏览器或-WebView2-总量高&#34; class=&#34;headerlink&#34; title=&#34;模式六：浏览器或 WebView2 总量高&#34;&gt;&lt;/a&gt;模式六：浏览器或 WebView2 总量高&lt;/h3&gt;&lt;p&gt;重点检查：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;标签页和扩展；&lt;/li&gt;
&lt;li&gt;后台运行设置；&lt;/li&gt;
&lt;li&gt;使用 WebView2 的桌面应用；&lt;/li&gt;
&lt;li&gt;是否有子进程残留；&lt;/li&gt;
&lt;li&gt;同名进程实例是否持续增长。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;二十五、一键审查脚本&#34;&gt;&lt;a href=&#34;#二十五、一键审查脚本&#34; class=&#34;headerlink&#34; title=&#34;二十五、一键审查脚本&#34;&gt;&lt;/a&gt;二十五、一键审查脚本&lt;/h2&gt;&lt;p&gt;将以下脚本保存为 &lt;code&gt;Handle-Audit.ps1&lt;/code&gt;。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-powershell&#34; data-language=&#34;powershell&#34;&gt;&lt;code class=&#34;language-powershell&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;param&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
    &lt;span class=&#34;token namespace&#34;&gt;[int]&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$ObserveSeconds&lt;/span&gt; = 60&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    &lt;span class=&#34;token namespace&#34;&gt;[int]&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$Top&lt;/span&gt; = 30&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;
    &lt;span class=&#34;token namespace&#34;&gt;[string]&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$OutputDirectory&lt;/span&gt; = &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
        &lt;span class=&#34;token function&#34;&gt;Join-Path&lt;/span&gt; &lt;span class=&#34;token variable&#34;&gt;$env&lt;/span&gt;:USERPROFILE &lt;span class=&#34;token string&#34;&gt;&#34;Desktop\HandleAudit&#34;&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token function&#34;&gt;Set-StrictMode&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Version Latest
&lt;span class=&#34;token function&#34;&gt;New-Item&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ItemType Directory &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Path &lt;span class=&#34;token variable&#34;&gt;$OutputDirectory&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;Force &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Out-Null&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;Get-FullProcessSnapshot&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$time&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Get-Date&lt;/span&gt;
    &lt;span class=&#34;token variable&#34;&gt;$cimProcesses&lt;/span&gt; = &lt;span class=&#34;token function&#34;&gt;Get-CimInstance&lt;/span&gt; Win32_Process &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ErrorAction SilentlyContinue
    &lt;span class=&#34;token variable&#34;&gt;$cimMap&lt;/span&gt; = @&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

    &lt;span class=&#34;token keyword&#34;&gt;foreach&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$item&lt;/span&gt; in &lt;span class=&#34;token variable&#34;&gt;$cimProcesses&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
        &lt;span class=&#34;token variable&#34;&gt;$cimMap&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token namespace&#34;&gt;[int]&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$item&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ProcessId&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; = &lt;span class=&#34;token variable&#34;&gt;$item&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

    &lt;span class=&#34;token function&#34;&gt;Get-Process&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;ErrorAction SilentlyContinue &lt;span class=&#34;token punctuation&#34;&gt;|&lt;/span&gt;
    &lt;span class=&#34;token function&#34;&gt;ForEach-Object&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
        &lt;span class=&#34;token variable&#34;&gt;$cim&lt;/span&gt; = &lt;span class=&#34;token variable&#34;&gt;$null&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$cimMap&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;ContainsKey&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token namespace&#34;&gt;[int]&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Id&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
            &lt;span class=&#34;token variable&#34;&gt;$cim&lt;/span&gt; = &lt;span class=&#34;token variable&#34;&gt;$cimMap&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token namespace&#34;&gt;[int]&lt;/span&gt;&lt;span class=&#34;token variable&#34;&gt;$_&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Id&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;
        &lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

